import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=id=>document.getElementById(id), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const worldEl=$('world');
let scene,camera,renderer,raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0), clock=new THREE.Clock();
let mode='explore',selected='vanguard',activeMode='',campaignStage=0,encounterIndex=0,round=1,gold=0,reviveUsed=false,gameOver=false;
let actors=[],obstacles=new Set(),tileMeshes=[],entities=[],exploreDecor=[],particles=[],isMoving=false,moveTask=null,toastTimer,turnToken=0;
let camAngle=Math.PI/4,camZoom=18,center=new THREE.Vector3(0,0,0),pointerDown=null,dragged=false,modalKind='intro';
const party={vanguard:{id:'vanguard',name:'Vanguard',title:'SER KAEL',hp:12,max:12,damage:3,move:4,range:1,x:-7.9,z:4.2,mesh:null,moved:false,acted:false,down:false},occultist:{id:'occultist',name:'Occultist',title:'MARA VEY',hp:8,max:8,damage:2,move:3,range:3,x:-8.8,z:5,mesh:null,moved:false,acted:false,down:false}};
const enemyDefs={undead:{name:'SHAMBLING UNDEAD',hp:6,damage:2,move:2,range:1,color:0x707467,kind:'melee'},archer:{name:'SKELETON ARCHER',hp:4,damage:2,move:3,range:4,color:0x9b8c72,kind:'ranged'},warden:{name:'GRAVE WARDEN',hp:18,damage:4,move:2,range:1,color:0x493a37,kind:'boss'}};
const fights=[{title:'AMBUSH IN THE WOODS',banner:'THE DEAD ARE RISING',zone:'forest',enemies:['undead','undead']},{title:'THE SUNKEN CRYPT',banner:'BONES IN THE DARK',zone:'crypt',enemies:['undead','archer']},{title:'THE WARDEN’S CHAMBER',banner:'THE GRAVE OPENS',zone:'boss',enemies:['warden']}];
const targets=[{x:0,z:0},{x:7,z:-5},{x:9,z:-10}];
function init3D(){
  scene=new THREE.Scene();scene.background=new THREE.Color(0x171b18);scene.fog=new THREE.FogExp2(0x171b18,.023);
  camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,120);camera.position.set(12,16,16);
  renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;worldEl.appendChild(renderer.domElement);
  scene.add(new THREE.HemisphereLight(0xb4bdaf,0x302a23,1.5));const moon=new THREE.DirectionalLight(0xe0d5bd,2.1);moon.position.set(-7,13,7);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-22;moon.shadow.camera.right=22;moon.shadow.camera.top=22;moon.shadow.camera.bottom=-22;scene.add(moon);
  buildExplore();camera.position.set(12,16,16);lookCamera();
  renderer.domElement.addEventListener('pointerdown',onPointerDown);renderer.domElement.addEventListener('pointerup',onPointerUp);renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('wheel',e=>{camZoom=clamp(camZoom+Math.sign(e.deltaY)*1.3,10,29);lookCamera()},{passive:true});
  window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
  animate();
}
function lookCamera(){let d=camZoom;camera.position.set(center.x+Math.sin(camAngle)*d*.78,center.y+d*.83,center.z+Math.cos(camAngle)*d*.78);camera.lookAt(center);}
function mesh(geo,mat,x,y,z,group=scene){let m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;group.add(m);return m}
const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});
function clearScene(){while(scene.children.length){const c=scene.children[0];scene.remove(c)} entities=[];tileMeshes=[];exploreDecor=[];particles=[];}
function setupLighting(zone='forest'){
 scene.background=new THREE.Color(zone==='forest'?0x171b18:0x151514);scene.fog=new THREE.FogExp2(zone==='forest'?0x171b18:0x151514,zone==='forest'?.023:.03);
 scene.add(new THREE.HemisphereLight(zone==='forest'?0xb4bdaf:0x8c8273,0x302a23,zone==='forest'?1.5:1.05));let moon=new THREE.DirectionalLight(0xd8d0bc,zone==='forest'?2:1.45);moon.position.set(-7,13,7);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-22;moon.shadow.camera.right=22;moon.shadow.camera.top=22;moon.shadow.camera.bottom=-22;scene.add(moon);
}
function buildExplore(){clearScene();mode='explore';setupLighting('forest');let ground=mesh(new THREE.PlaneGeometry(54,54),mat(0x34362e),0,-.16,0);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;
 // winding earth track
 const pathPts=[new THREE.Vector3(-8,-.12,5),new THREE.Vector3(-5,-.12,2.5),new THREE.Vector3(-3,-.12,0),new THREE.Vector3(0,-.12,-.2),new THREE.Vector3(2,-.12,-2),new THREE.Vector3(4,-.12,-4),new THREE.Vector3(7,-.12,-5),new THREE.Vector3(8,-.12,-8),new THREE.Vector3(10,-.12,-10)];let curve=new THREE.CatmullRomCurve3(pathPts);let path=mesh(new THREE.TubeGeometry(curve,64,1.05,8,false),mat(0x51483a),0,0,0);path.receiveShadow=true;
 // camp
 addCamp(-9,4); // woods and graveyard
 for(let i=0;i<58;i++){let x=(Math.random()-.5)*34,z=(Math.random()-.5)*31;if(distanceToPath(x,z)<2.05)continue;if(Math.hypot(x+9,z-4)<4)continue;addTree(x,z,Math.random()*.7+.7)}
 for(let [x,z,r] of [[-1,-1,1],[1,-.8,1.1],[2,1,.8],[5,-3,.9],[6,-7,.7],[4,-8,.75]])addGrave(x,z,r);
 addRuin(2,2);addCrypt(8.5,-8.5);addTorches();
 for(const c of Object.values(party)){c.mesh=createHero(c.id);scene.add(c.mesh);placeHero(c)}
 // far edge fog silhouettes
 addFarRuins();$('location-title').textContent=campaignStage===0?'THE ASHEN CAMP':campaignStage===1?'THE OLD FOREST':campaignStage===2?'THE SUNKEN CRYPT':'THE WARDEN’S CHAMBER';
 center.set(-2,0,0);camZoom=18;lookCamera();updatePartyUI();}
function distanceToPath(x,z){const pts=[[-8,5],[-5,2.5],[-3,0],[0,-.2],[2,-2],[4,-4],[7,-5],[8,-8],[10,-10]];return Math.min(...pts.map(p=>Math.hypot(x-p[0],z-p[1])))}
function addTree(x,z,s=1){let trunk=mesh(new THREE.CylinderGeometry(.13*s,.24*s,1.55*s,6),mat(0x38332a),x,.62*s,z);trunk.rotation.z=(Math.random()-.5)*.12;let foliage=mesh(new THREE.ConeGeometry(.85*s,2.4*s,6),mat(Math.random()>.5?0x30372e:0x34372e),x,2.05*s,z);foliage.rotation.y=Math.random()*2;exploreDecor.push(trunk,foliage);if(Math.random()<.35){let f=mesh(new THREE.ConeGeometry(.62*s,1.8*s,6),mat(0x292f28),x+.25*s,2.65*s,z+.12*s);exploreDecor.push(f)}}
function addGrave(x,z,s=1){let stone=mesh(new THREE.BoxGeometry(.8*s,.16*s,.42*s),mat(0x555349),x,.12*s,z);stone.rotation.y=Math.random()*1.7;let cross=mesh(new THREE.BoxGeometry(.16*s,.85*s,.2*s),mat(0x777366),x,.56*s,z);cross.rotation.z=(Math.random()-.5)*.23;let cap=mesh(new THREE.BoxGeometry(.54*s,.16*s,.22*s),mat(0x777366),x,.77*s,z);cap.rotation.z=cross.rotation.z;exploreDecor.push(stone,cross,cap)}
function addRuin(x,z){for(let i=0;i<4;i++){let p=mesh(new THREE.BoxGeometry(.65,.1+Math.random()*.35,.7),mat(0x5b584e),x+i*.75,.25,z);p.rotation.y=Math.random()*.5;exploreDecor.push(p)}let col=mesh(new THREE.CylinderGeometry(.28,.35,2.6,7),mat(0x55544b),x+1,1.15,z+1);col.rotation.z=.13;exploreDecor.push(col)}
function addCamp(x,z){let tent=mesh(new THREE.ConeGeometry(2.05,2.3,4),mat(0x554b3b),x,.98,z);tent.rotation.y=Math.PI/4;let bed=mesh(new THREE.BoxGeometry(1.7,.25,.8),mat(0x40382e),x-2,.2,z+1);bed.rotation.y=.5;for(let i=0;i<3;i++){let log=mesh(new THREE.CylinderGeometry(.12,.12,1.1,7),mat(0x514231),x+2.2+i*.17,.1,z+1.4);log.rotation.z=Math.PI/2;log.rotation.y=.35}let fire=mesh(new THREE.IcosahedronGeometry(.35,0),mat(0xd17d39),x+2.5,.28,z);let light=new THREE.PointLight(0xff9d50,12,8);light.position.set(x+2.5,1,z);scene.add(light);exploreDecor.push(tent,bed,fire)}
function addCrypt(x,z){let stone=mat(0x504d45);for(let i=0;i<3;i++){let col=mesh(new THREE.BoxGeometry(.45,2.5,.5),stone,x-1.6+i*1.6,1.2,z);exploreDecor.push(col)}let lintel=mesh(new THREE.BoxGeometry(4, .55,.75),mat(0x625e52),x,2.55,z);exploreDecor.push(lintel);let inner=mesh(new THREE.BoxGeometry(2.25,2,.15),mat(0x101210),x,1.15,z-.25);exploreDecor.push(inner);let stairs=mesh(new THREE.BoxGeometry(3, .24,2.3),mat(0x4c4940),x,0,z-1.5);stairs.rotation.x=.1;exploreDecor.push(stairs);let l=new THREE.PointLight(0xc1723e,5,7);l.position.set(x,1.5,z-2);scene.add(l)}
function addTorches(){for(const [x,z] of [[-6,2],[0,-1],[5,-5],[8,-7]]){let post=mesh(new THREE.CylinderGeometry(.07,.1,1.7,6),mat(0x433a2d),x,.78,z);let flame=mesh(new THREE.IcosahedronGeometry(.16,1),mat(0xd38c4c),x,1.68,z);let light=new THREE.PointLight(0xe0924a,3.8,6);light.position.set(x,1.75,z);scene.add(light);exploreDecor.push(post,flame)}}
function addFarRuins(){for(let i=0;i<7;i++){let x=-15+i*5,z=-12-Math.random()*5;let r=mesh(new THREE.BoxGeometry(1+Math.random(),2+Math.random()*2,.8),mat(0x42433c),x,1,z);exploreDecor.push(r)}}
function createHero(id){const g=new THREE.Group(),v=id==='vanguard',armor=mat(v?0x51534d:0x493e48),cloth=mat(v?0x403a31:0x393039),skin=mat(v?0x927966:0x81716f),iron=mat(0x77756a);let torso=mesh(new THREE.CylinderGeometry(.3,.4,.85,7),armor,0,1.18,0,g);let cloak=mesh(new THREE.ConeGeometry(.48,.95,6),cloth,0,1.07,-.19,g);cloak.rotation.x=-.14;let head=mesh(new THREE.SphereGeometry(.24,8,7),skin,0,1.85,0,g);let hood=mesh(new THREE.SphereGeometry(.3,8,6),v?iron:cloth,0,1.94,-.03,g);hood.scale.set(1,.72,.92);for(let side of [-1,1]){let leg=mesh(new THREE.CylinderGeometry(.11,.14,.58,6),cloth,side*.18,.45,0,g);leg.position.z=0;let arm=mesh(new THREE.CylinderGeometry(.12,.15,.65,6),armor,side*.39,1.28,0,g);arm.rotation.z=side*-.18}
 if(v){let shield=mesh(new THREE.BoxGeometry(.5,.7,.13),iron,-.56,1.15,.06,g);shield.rotation.z=-.1;let sword=mesh(new THREE.BoxGeometry(.08,.85,.08),iron,.52,1.38,.05,g);sword.rotation.z=-.28;let h=mesh(new THREE.BoxGeometry(.13,.25,.13),mat(0x46362d),.52,.88,.05,g)}else{let staff=mesh(new THREE.CylinderGeometry(.045,.065,1.8,6),mat(0x6d5542),.55,.95,.05,g);staff.rotation.z=-.11;let orb=mesh(new THREE.IcosahedronGeometry(.18,1),mat(0x93748e),.5,1.93,.05,g);orb.material.emissive=new THREE.Color(0x382538);orb.material.emissiveIntensity=.9}
 g.userData.baseY=0;g.userData.bob=Math.random()*6;g.userData.id=id;return g;}
function placeHero(c){if(!c.mesh)return;c.mesh.position.set(c.x,0,c.z);c.mesh.rotation.y=c.id==='vanguard'?-.35:.2}
function makeBar(color=0x9a3e34){let g=new THREE.Group();let bg=mesh(new THREE.PlaneGeometry(1.15,.11),mat(0x201e1a),0,0,0,g),fill=mesh(new THREE.PlaneGeometry(1.1,.07),mat(color),0,0,.005,g);g.userData.fill=fill;g.position.y=2.45;return g}
function updateHeroBar(c){if(!c.mesh)return;let old=c.mesh.getObjectByName('hpbar');if(old)c.mesh.remove(old);if(c.down)return;let b=makeBar(c.id==='vanguard'?0x8c9a6b:0x98717a);b.name='hpbar';b.userData.fill.scale.x=Math.max(.02,c.hp/c.max);b.userData.fill.position.x=-(1-c.hp/c.max)*.55;b.position.y=2.38;c.mesh.add(b)}

function buildBattle(fight){clearScene();mode='battle';setupLighting(fight.zone);center.set(0,0,0);camAngle=Math.PI/4;camZoom=13.8;lookCamera();
 const floor=mesh(new THREE.PlaneGeometry(19,15),mat(fight.zone==='crypt'?0x34312b:0x35362f),0,-.25,0);floor.rotation.x=-Math.PI/2;
 // A compact 9 x 7 tactical field. Tile colors are deliberately subdued until a command is chosen.
 obstacles=new Set();for(const p of (fight.zone==='forest'?[[1,0],[1,1],[-1,-1],[3,2]]:fight.zone==='crypt'?[[0,0],[0,1],[3,-1],[-2,2]]:[[0,1],[0,2],[3,0],[-3,-1]]))obstacles.add(key(p[0],p[1]));
 const tileMat=mat(0x48463d);for(let z=-3;z<=3;z++)for(let x=-4;x<=4;x++){let t=mesh(new THREE.BoxGeometry(.97,.08,.97),tileMat,x,-.1,z);t.userData.tile={x,z};tileMeshes.push(t);let edge=mesh(new THREE.EdgesGeometry(new THREE.BoxGeometry(.98,.085,.98)),new THREE.LineBasicMaterial({color:0x8c8069,transparent:true,opacity:.32}),x,-.1,z);edge.userData.tile={x,z};tileMeshes.push(edge);}
 // battlefield edge stones, crypt pillars, braziers
 for(let x=-5;x<=5;x+=2){let block=mesh(new THREE.BoxGeometry(.55,.65,.55),mat(0x4c4941),x,.1,-4);let block2=mesh(new THREE.BoxGeometry(.55,.65,.55),mat(0x4c4941),x,.1,4)}
 for(const [x,z] of [[-5,-3],[5,-3],[-5,3],[5,3]]){let p=mesh(new THREE.CylinderGeometry(.35,.43,3.8,7),mat(0x514d43),x,1.8,z);p.rotation.z=(x<0?-.04:.04)}
 if(fight.zone!=='forest'){for(const [x,z] of [[-2,-2],[2,2]]){let slab=mesh(new THREE.BoxGeometry(1.7,.45,.65),mat(0x514b40),x,.05,z);slab.rotation.y=.3}}
 // grid glyphs and shadowy ambient fire
 for(const [x,z] of [[-5,-3],[5,3]]){let flame=mesh(new THREE.IcosahedronGeometry(.17,1),mat(0xc17b41),x,.8,z);let light=new THREE.PointLight(0xdb8140,4,8);light.position.set(x,1,z);scene.add(light)}
 entities=[];
 const positions=fight.enemies.length===1?[[2,0]]:fight.zone==='forest'?[[2,-1],[3,1]]:[[2,-1],[3,2]];
 for(const c of Object.values(party)){c.moved=false;c.acted=false;c.down=c.hp<=0;let pos=c.id==='vanguard'?[-3,0]:[-3,1];c.gx=pos[0];c.gz=pos[1];c.mesh.position.set(c.gx,0,c.gz);c.mesh.rotation.y=c.id==='vanguard'?-.35:.2;if(c.down)c.mesh.visible=false;else c.mesh.visible=true;updateHeroBar(c);entities.push(c)}
 fight.enemies.forEach((type,i)=>{let e={...enemyDefs[type],id:'enemy'+i,type,hp:enemyDefs[type].hp,max:enemyDefs[type].hp,gx:positions[i][0],gz:positions[i][1],moved:false,acted:false,down:false};e.mesh=createEnemy(e);e.mesh.position.set(e.gx,0,e.gz);scene.add(e.mesh);updateEnemyBar(e);entities.push(e)});
 $('battle-title').textContent=fight.title;$('battle-head').classList.remove('hidden');$('battle-status').classList.remove('hidden');$('battle-dock').classList.remove('hidden');$('explore-dock').classList.add('hidden');$('objective').classList.add('hidden');$('party-tip').textContent='Each hero has one move and one action per round.';$('battle-head').style.display='flex';
 round=1;reviveUsed=false;activeMode='';$('round-count').textContent='1';$('combat-banner').classList.remove('hidden');$('banner-text').textContent=fight.banner;setTimeout(()=>$('combat-banner').classList.add('hidden'),1900);selected=party.vanguard.down?'occultist':'vanguard';syncUI();updatePartyUI();showToast('Your company acts first. Choose your opening move.');}
function createEnemy(e){let g=new THREE.Group(),boss=e.type==='warden',arch=e.type==='archer',bone=mat(e.color),dark=mat(boss?0x292522:0x38352e),rust=mat(boss?0x674739:0x74614a);let torso=mesh(new THREE.CylinderGeometry(boss?.42:.28,boss?.55:.35,boss?1.15:.8,7),dark,0,boss?1.35:1.13,0,g);let rib=mesh(new THREE.BoxGeometry(boss?.75:.43,.1,.38),rust,0,boss?1.65:1.37,.03,g);let head=mesh(new THREE.SphereGeometry(boss?.34:.24,7,6),bone,0,boss?2.16:1.82,0,g);let hood=mesh(new THREE.ConeGeometry(boss?.42:.29,.47,7),dark,0,boss?2.42:2.01,-.02,g);for(const s of [-1,1]){let leg=mesh(new THREE.CylinderGeometry(.12,.16,boss?.7:.55,6),dark,s*.2,.36,0,g);let arm=mesh(new THREE.CylinderGeometry(.11,.15,boss?.9:.67,6),dark,s*(boss?.49:.38),1.3,0,g);arm.rotation.z=s*-.22}
 let weapon=mesh(new THREE.BoxGeometry(boss?.12:.08,boss?1.5:.85,.08),rust,boss?.63:.47,boss?1.45:1.18,.03,g);weapon.rotation.z=-.2;if(arch){let bow=mesh(new THREE.TorusGeometry(.35,.035,5,12,Math.PI),rust,.48,1.35,.1,g);bow.rotation.z=Math.PI/2;let quiver=mesh(new THREE.CylinderGeometry(.12,.14,.56,6),bone,-.32,1.4,-.23,g)}if(boss){for(let s of [-1,1]){let horn=mesh(new THREE.ConeGeometry(.15,.55,5),rust,s*.25,2.4,-.03,g);horn.rotation.z=s*.5}}
 g.userData.bob=Math.random()*6;g.userData.type=e.type;g.userData.baseY=0;return g;}
function updateEnemyBar(e){let old=e.mesh.getObjectByName('hpbar');if(old)e.mesh.remove(old);let b=makeBar(e.type==='warden'?0xa45b45:0x9a493b);b.name='hpbar';b.userData.fill.scale.x=Math.max(.02,e.hp/e.max);b.userData.fill.position.x=-(1-e.hp/e.max)*.55;b.position.y=e.type==='warden'?2.9:2.35;e.mesh.add(b)}
const key=(x,z)=>`${x},${z}`, manhattan=(a,b)=>Math.abs(a.gx-b.gx)+Math.abs(a.gz-b.gz);
function occupied(x,z,exclude=null){return entities.some(e=>e!==exclude&&!e.down&&e.gx===x&&e.gz===z)}
function isBlocked(x,z){return x< -4||x>4||z< -3||z>3||obstacles.has(key(x,z))}
function getReach(actor,max){let start=key(actor.gx,actor.gz),dist=new Map([[start,0]]),prev=new Map(),q=[[actor.gx,actor.gz]];while(q.length){let [x,z]=q.shift(),d=dist.get(key(x,z));if(d>=max)continue;for(let [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,nz=z+dz,k=key(nx,nz);if(dist.has(k)||isBlocked(nx,nz)||occupied(nx,nz,actor))continue;dist.set(k,d+1);prev.set(k,key(x,z));q.push([nx,nz])}}return {dist,prev}}
function routeTo(actor,x,z){let reach=getReach(actor,9),k=key(x,z);if(!reach.dist.has(k))return null;let path=[];while(k!==key(actor.gx,actor.gz)){let [px,pz]=k.split(',').map(Number);path.unshift([px,pz]);k=reach.prev.get(k)}return path}
function paintGrid(){for(let o of tileMeshes){if(o.userData.tile&&o.material.color)o.material.color.setHex(0x48463d)}if(mode!=='battle')return;if(activeMode==='move'&&!party[selected].moved&&!party[selected].down){let r=getReach(party[selected],party[selected].move);for(let o of tileMeshes){let t=o.userData.tile;if(t&&r.dist.has(key(t.x,t.z))){o.material.color.setHex(o.type==='LineSegments'?0x8fb285:0x596f50)}}}
 if(activeMode==='attack'||activeMode==='ability'){for(const e of entities.filter(e=>e.id.startsWith('enemy')&&!e.down)){if(canTarget(party[selected],e,activeMode)){for(let o of tileMeshes){if(o.userData.tile&&o.userData.tile.x===e.gx&&o.userData.tile.z===e.gz)o.material.color.setHex(0x95584b)}}}}}
function canTarget(a,e,which){let range=which==='ability'?(a.id==='vanguard'?1:1):a.range;return !a.down&&!a.acted&&!e.down&&manhattan(a,e)<=range&&(which!=='ability'||(a.id==='vanguard'||a.id==='occultist'))}
function moveActor(actor,x,z,callback){let path=routeTo(actor,x,z);if(!path||!path.length){callback?.(false);return}let maximum=actor.move;if(actor.id?.startsWith('enemy'))maximum=actor.move;path=path.slice(0,maximum);actor.moved=true;isMoving=true;const start=performance.now(),duration=path.length*190,from={x:actor.mesh.position.x,z:actor.mesh.position.z};function tick(now){let progress=clamp((now-start)/duration,0,1),segment=progress*path.length,idx=Math.min(path.length-1,Math.floor(segment)),local=segment-idx;let prev=idx===0?from:{x:path[idx-1][0],z:path[idx-1][1]},next=path[idx];actor.mesh.position.x=THREE.MathUtils.lerp(prev.x,next[0],local);actor.mesh.position.z=THREE.MathUtils.lerp(prev.z,next[1],local);actor.mesh.rotation.y=Math.atan2(next[0]-prev.x,next[1]-prev.z);if(progress<1)requestAnimationFrame(tick);else{actor.gx=path[path.length-1][0];actor.gz=path[path.length-1][1];actor.mesh.position.set(actor.gx,0,actor.gz);isMoving=false;callback?.(true);syncUI()}}requestAnimationFrame(tick)}

function onPointerDown(e){pointerDown={x:e.clientX,y:e.clientY,id:e.pointerId};dragged=false;renderer.domElement.setPointerCapture?.(e.pointerId)}
