function updateHeroBar(c){if(!c.mesh)return;let old=c.mesh.getObjectByName('hpbar');if(old)c.mesh.remove(old);if(c.down)return;let b=makeBar(c.id==='vanguard'?0x8c9a6b:0x98717a);b.name='hpbar';b.userData.fill.scale.x=Math.max(.02,c.hp/c.max);b.userData.fill.position.x=-(1-c.hp/c.max)*.55;b.position.y=2.38;c.mesh.add(b)}

const say=(text)=>{const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)};
function updatePartyUI(){for(const c of Object.values(party)){const hp=$(`hp-${c.id}`),bar=$(`hpbar-${c.id}`),status=$(`status-${c.id}`),card=$(`card-${c.id}`);if(hp)hp.textContent=Math.max(0,c.hp);if(bar)bar.style.width=`${Math.max(0,c.hp/c.max*100)}%`;if(status)status.textContent=c.down?'DOWNED':c.hp<=3?'WOUNDED':c.moved&&c.acted?'SPENT':'READY';if(card){card.classList.toggle('selected',selected===c.id);card.classList.toggle('down',c.down)}}$('gold-count').textContent=gold}
function setModeUI(){const battle=mode==='battle';$('objective').classList.toggle('hidden',battle);$('battle-head').classList.toggle('hidden',!battle);$('battle-status').classList.toggle('hidden',!battle);$('battle-dock').classList.toggle('hidden',!battle);$('explore-dock').classList.toggle('hidden',battle);$('party-tip').textContent=battle?'Choose a hero, then move and use an action.':'Select a company member, then click the path to travel.'}
function removeWorld(){while(scene.children.length){const o=scene.children[0];scene.remove(o)}entities=[];tileMeshes=[];exploreDecor=[];particles=[];actors=[]}
function makeEnemy(type,x,z){const def=enemyDefs[type],g=new THREE.Group(),body=mesh(new THREE.CylinderGeometry(.34,.4,.95,6),mat(def.color),0,1.05,0,g),head=mesh(new THREE.SphereGeometry(.28,7,6),mat(type==='warden'?0x6a5145:0xb4a88f),0,1.72,0,g);if(type==='archer'){const bow=mesh(new THREE.TorusGeometry(.35,.035,5,8,Math.PI),mat(0x664c36),.42,1.35,0,g);bow.rotation.z=Math.PI/2}if(type==='warden'){const crown=mesh(new THREE.ConeGeometry(.45,.55,5),mat(0x4c3730),0,2.1,0,g);crown.rotation.z=Math.PI}g.position.set(x,0,z);g.userData={type,hp:def.hp,max:def.hp,damage:def.damage,range:def.range,move:def.move,kind:def.kind,name:def.name,team:'enemy'};const bar=makeBar(0xa34b3e);bar.name='hpbar';bar.userData.fill.scale.x=1;bar.position.y=2.5;g.add(bar);scene.add(g);return g}
function startBattle(index){encounterIndex=index;mode='battle';activeMode='';round=1;removeWorld();setupLighting(index===1?'crypt':'forest');const floor=mesh(new THREE.PlaneGeometry(13,11),mat(index===2?0x39352f:0x393b32),0,-.12,0);floor.rotation.x=-Math.PI/2;
 for(let z=-3;z<=3;z++)for(let x=-4;x<=4;x++){const tile=mesh(new THREE.PlaneGeometry(.96,.96),mat((x+z)%2?0x4b493f:0x514d42),x,0,z);tile.rotation.x=-Math.PI/2;tile.userData={tile:true,x,z};tileMeshes.push(tile)}
 const rocks=index===0?[[-1,0],[1,-1]]:index===1?[[0,0],[1,1],[-1,-1]]:[[0,1],[1,-1]];for(const [x,z]of rocks){obstacles.add(`${x},${z}`);const r=mesh(new THREE.DodecahedronGeometry(.48,0),mat(0x625e51),x,.35,z);r.scale.y=.8}
 for(const c of Object.values(party)){c.mesh=createHero(c.id);scene.add(c.mesh);c.x=c.id==='vanguard'?-3:-3;c.z=c.id==='vanguard'?1:-1;c.mesh.position.set(c.x,0,c.z);c.down=c.hp<=0;c.moved=false;c.acted=false;if(c.down)c.mesh.visible=false;updateHeroBar(c)}
 let positions=index===0?[[2,-1],[3,1]]:index===1?[[2,-1],[3,1]]:[[2,0]];actors=[];fights[index].enemies.forEach((type,i)=>{const m=makeEnemy(type,...positions[i]);actors.push(m)});
 selected=Object.values(party).find(c=>!c.down)?.id||'vanguard';center.set(0,0,0);camAngle=Math.PI/4;camZoom=14;lookCamera();$('battle-title').textContent=fights[index].title;$('round-count').textContent=round;$('banner-text').textContent=fights[index].banner;$('combat-banner').classList.remove('hidden');setTimeout(()=>$('combat-banner').classList.add('hidden'),1800);setModeUI();updatePartyUI();updateBattleUI();}
function updateBattleUI(){const c=party[selected];if(!c)return;$('selected-name').textContent=c.id==='vanguard'?'VANGUARD':'OCCULTIST';$('ability-label').textContent=c.id==='vanguard'?'SHIELD BASH':'GRAVE BOLT';$('turn-status').textContent=`${c.name.toUpperCase()}${c.down?' — DOWNED':'’S TURN'}`;$('move-status').innerHTML=`MOVE <b>${c.moved?'0':c.move}</b>`;$('action-status').innerHTML=`ACTION <b>${c.acted?'SPENT':'READY'}</b>`;$('round-count').textContent=round;updatePartyUI();highlightTiles()}
function highlightTiles(){for(const t of tileMeshes){const{x,z}=t.userData,active=activeMode==='move'&&Math.abs(x-party[selected].x)+Math.abs(z-party[selected].z)<=party[selected].move&&!obstacles.has(`${x},${z}`);t.material.color.setHex(active?0x71805a:((x+z)%2?0x4b493f:0x514d42));}}
function gridDistance(a,b){return Math.abs(a.x-b.x)+Math.abs(a.z-b.z)}
function doHeroMove(c,x,z){if(c.moved||c.down)return say('This hero has already moved.');let d=gridDistance(c,{x,z});if(d<1||d>c.move||obstacles.has(`${x},${z}`)||[...Object.values(party),...actors].some(a=>a!==c&&!a.userData?.dead&&Math.round(a.x??a.position.x)===x&&Math.round(a.z??a.position.z)===z))return say('That tile cannot be reached.');c.x=x;c.z=z;c.mesh.position.set(x,0,z);c.moved=true;activeMode='';updateBattleUI()}
function enemyAt(x,z){return actors.find(a=>!a.userData.dead&&Math.round(a.position.x)===x&&Math.round(a.position.z)===z)}
function hurtEnemy(e,n){const d=e.userData;d.hp-=n;const b=e.getObjectByName('hpbar');if(b){const f=Math.max(.02,d.hp/d.max);b.userData.fill.scale.x=f;b.userData.fill.position.x=-(1-f)*.55}e.position.y=.12;if(d.hp<=0){d.dead=true;d.hp=0;setTimeout(()=>{if(e.parent)e.parent.remove(e)},350);gold+=d.type==='warden'?30:8;say(`${d.name} is slain. +${d.type==='warden'?30:8} gold.`);updatePartyUI();if(actors.every(a=>a.userData.dead))setTimeout(victory,700)}}
function attackTarget(c,e,ability=false){if(!e||e.userData.dead)return say('Choose a living enemy.');const dist=gridDistance(c,{x:Math.round(e.position.x),z:Math.round(e.position.z)}),range=ability?(c.id==='vanguard'?1:3):c.range;if(dist>range)return say('Target is out of range.');if(c.acted)return say('This hero has already used an action.');const damage=ability?(c.id==='vanguard'?4:3):c.damage;hurtEnemy(e,damage);c.acted=true;updateBattleUI()}
function useAbility(c){if(c.down)return say('A downed hero cannot act.');if(c.acted)return say('Action already spent.');if(c.id==='occultist'){const fallen=Object.values(party).find(p=>p.down);if(fallen&&!reviveUsed&&gridDistance(c,fallen)<=2){fallen.down=false;fallen.hp=5;fallen.mesh.visible=true;fallen.mesh.position.set(fallen.x,0,fallen.z);updateHeroBar(fallen);reviveUsed=true;c.acted=true;say(`${fallen.name} returns from the brink.`);updateBattleUI();return}if(!fallen&&actors.some(a=>!a.userData.dead&&gridDistance(c,{x:Math.round(a.position.x),z:Math.round(a.position.z)})<=3)){activeMode='ability';$('selection-note').classList.remove('hidden');return}if(fallen&&reviveUsed)return say('The grave will not yield twice.')}activeMode='ability';$('selection-note').classList.remove('hidden');}
function doEnemyTurn(){activeMode='';$('selection-note').classList.add('hidden');$('turn-status').textContent='THE DEAD TAKE THEIR TURN';const token=++turnToken;let i=0;const step=()=>{if(token!==turnToken||gameOver)return;if(i>=actors.length){if(Object.values(party).every(c=>c.down||c.hp<=0)){finishGame(false);return}round++;for(const c of Object.values(party)){c.moved=false;c.acted=false}updateBattleUI();say(`Round ${round}. Your company is ready.`);return}const e=actors[i++],d=e.userData;if(d.dead)return step();const alive=Object.values(party).filter(c=>!c.down&&c.hp>0);if(!alive.length)return finishGame(false);alive.sort((a,b)=>gridDistance(e.position,{x:a.x,z:a.z})-gridDistance(e.position,{x:b.x,z:b.z}));const target=alive[0],dist=gridDistance(e.position,{x:target.x,z:target.z});if(dist<=d.range){target.hp=Math.max(0,target.hp-d.damage);if(target.hp===0){target.down=true;target.mesh.visible=false;say(`${target.name} is down!`)}else say(`${d.name} strikes ${target.name} for ${d.damage}.`);updatePartyUI();}else{const dx=Math.sign(target.x-e.position.x),dz=Math.sign(target.z-e.position.z);let nx=e.position.x+dx,nz=e.position.z;if(obstacles.has(`${nx},${nz}`)||[...Object.values(party),...actors].some(a=>a!==e&&!a.down&&!a.userData?.dead&&Math.round(a.x??a.position.x)===nx&&Math.round(a.z??a.position.z)===nz)){nx=e.position.x;nz=e.position.z+dz}if(!obstacles.has(`${nx},${nz}`)){e.position.set(nx,0,nz)}}setTimeout(step,500)};step()}
function victory(){if(encounterIndex===2){finishGame(true);return}mode='explore';campaignStage=encounterIndex+1;for(const c of Object.values(party)){c.hp=Math.min(c.max,c.hp+2);c.down=false;c.mesh=null;c.x=-7.9;c.z=4.2}$('location-title').textContent=campaignStage===1?'THE OLD FOREST':campaignStage===2?'THE SUNKEN CRYPT':'THE WARDEN’S CHAMBER';$('objective-text').textContent=campaignStage===1?'Follow the old road to the sunken crypt.':'Enter the crypt and face the Grave Warden.';$('objective-step').textContent=campaignStage===1?'II / III':'III / III';removeWorld();buildExplore();center.set(campaignStage===1?1:6,0,campaignStage===1?-2:-6);lookCamera();setModeUI();showEvent('THE PATH AHEAD',campaignStage===1?'A LIGHT BELOW THE STONES':'THE WARDEN’S CHAMBER','A short rest steadies your company. The road descends into older darkness.','CONTINUE');}
function finishGame(won){gameOver=true;mode='finished';const modal=$('modal');$('modal-eyebrow').textContent=won?'THE FIRST DESCENT COMPLETE':'YOUR COMPANY HAS FALLEN';$('modal-title').innerHTML=won?'THE GRAVE<br><em>IS SILENT</em>':'THE DARK<br><em>CLAIMS ALL</em>';$('modal-copy').textContent=won?'The Grave Warden is destroyed. Dawn finds the borderlands changed, but no longer haunted. Your company leaves the crypt with '+gold+' gold.':'The dead close in beneath the old stones. Your oath ends here, but the descent may begin again.';$('modal-controls').textContent='THREE ENCOUNTERS · TWO SOULS · ONE DESCENT';$('modal-primary').textContent='PLAY AGAIN →';$('modal').classList.remove('hidden');$('modal-primary').onclick=()=>location.reload()}
function showEvent(title,heading,copy,button){$('event-title').innerHTML=heading;$('event-copy').textContent=copy;$('event-primary').textContent=button+' →';$('event-card').classList.remove('hidden');$('event-primary').onclick=()=>{$('event-card').classList.add('hidden');if(campaignStage===0)startBattle(0);else{center.set(campaignStage===1?1:6,0,campaignStage===1?-2:-6);lookCamera()}}}
function finishExplore(){if(campaignStage===0)showEvent('THE PATH AHEAD','A FAMILIAR<br>STILLNESS','The wind dies. Something drags itself between the trees.','DRAW STEEL');else if(campaignStage===1)showEvent('THE PATH AHEAD','BONES IN THE DARK','A cold blue light flickers beyond the broken arch.','DESCEND');else showEvent('THE PATH AHEAD','THE GRAVE OPENS','Stone grinds below. The Grave Warden is waiting.','ENTER THE CRYPT')}

