function animateDown(g){if(!g)return;g.userData.downAt=performance.now();g.userData.motion=null;g.userData.action=null}
function updateActorAnimation(g,now,time){const d=g.userData;if(d.motion){const t=clamp((now-d.motion.start)/d.motion.duration,0,1),smooth=t*t*(3-2*t);g.position.lerpVectors(d.motion.from,d.motion.to,smooth);g.position.y+=Math.sin(t*Math.PI*6)*.055*(1-t);if(t>=1){g.position.copy(d.motion.to);d.motion=null}}
 if(d.action){const a=d.action,t=clamp((now-a.start)/a.duration,0,1),pulse=Math.sin(t*Math.PI);if(a.type==='attack'){g.position.x=a.base.x+a.dir.x*.38*pulse;g.position.z=a.base.z+a.dir.z*.38*pulse;g.rotation.z=Math.sin(t*Math.PI)*-.22}else if(a.type==='cast'){g.position.y=.12*pulse;g.rotation.z=Math.sin(t*Math.PI*2)*.08;for(const arm of d.arms||[])arm.rotation.x=-.8*pulse}if(t>=1){g.position.copy(a.base);g.rotation.z=0;for(const arm of d.arms||[])arm.rotation.x=0;d.action=null}}
 if(d.hitAt&&now-d.hitAt>190){g.traverse(o=>{if(o.isMesh&&o.material)for(const m of(Array.isArray(o.material)?o.material:[o.material]))if(m.userData.hitBase!==undefined){m.emissive.setHex(m.userData.hitBase);delete m.userData.hitBase}});d.hitAt=0}
 if(d.dead&&d.deathAt){const t=clamp((now-d.deathAt)/900,0,1);g.rotation.z=t*1.35;g.position.y=-t*.8;g.scale.setScalar(1-t*.48);if(t>=1){g.visible=false;d.deathAt=0}}
 if(d.downAt){const t=clamp((now-d.downAt)/420,0,1);g.rotation.z=t*.95;g.position.y=-t*.3;g.scale.y=1-t*.35;if(t>=1)d.downAt=0}
}

